/**
 * Desc:
 *
 * @author panguanjing
 * @date 2020/10/30
 */
@Getter
@Setter
@Builder
@EqualsAndHashCode(callSuper = false)
public class QuerySpecification extends BaseQueryBody {

    private Select select;

    private List<Hint> hints;

    private BaseRelation from;

    private BaseExpression where;

    private GroupBy groupBy;

    private BaseExpression having;

    private OrderBy orderBy;

    private ClusterBy clusterBy;

    private DistributeBy distributeBy;

    private SortBy sortBy;

    private Offset offset;

    private Node limit;

    public QuerySpecification(Select select, BaseRelation from) {
        this(null, select, null, from, null, null, null,
            null, null, null, null, null, null);
    }

    public QuerySpecification(NodeLocation location,
                              Select select, List<Hint> hints, BaseRelation from, BaseExpression where,
                              GroupBy groupBy, BaseExpression having,
                              OrderBy orderBy,
                              ClusterBy clusterBy,
                              DistributeBy distributeBy,
                              SortBy sortBy,
                              Offset offset, Node limit) {
        super(location);
        this.select = select;
        this.hints = hints;
        this.from = from;
        this.where = where;
        this.groupBy = groupBy;
        this.having = having;
        this.orderBy = orderBy;
        this.clusterBy = clusterBy;
        this.distributeBy = distributeBy;
        this.sortBy = sortBy;
        this.offset = offset;
        this.limit = limit;
    }

    public QuerySpecification(Select select, List<Hint> hints, BaseRelation from, BaseExpression where,
                              GroupBy groupBy, BaseExpression having,
                              OrderBy orderBy,
                              ClusterBy clusterBy,
                              DistributeBy distributeBy,
                              SortBy sortBy,
                              Offset offset,
                              Node limit) {
        this(null, select, hints, from, where, groupBy, having, orderBy, clusterBy, distributeBy, sortBy, offset, limit);
    }

    @Override
    public List<? extends Node> getChildren() {
        ImmutableList.Builder<Node> nodes = ImmutableList.builder();
        nodes.add(select);
        if (hints != null && !hints.isEmpty()) {
            nodes.addAll(hints);
        }
        if (from != null) {
            nodes.add(from);
        }
        if (where != null) {
            nodes.add(where);
        }
        if (groupBy != null) {
            nodes.add(groupBy);
        }
        if (having != null) {
            nodes.add(having);
        }
        if (orderBy != null) {
            nodes.add(orderBy);
        }
        if (offset != null) {
            nodes.add(offset);
        }
        if (limit != null) {
            nodes.add(limit);
        }
        return nodes.build();
    }

    @Override
    public <R, C> R accept(IAstVisitor<R, C> visitor, C context) {
        return visitor.visitQuerySpecification(this, context);
    }
}

